"""Generate the Mac-only offline guide from the shared control map."""
import html
import json
from pathlib import Path
import sys

source = Path(__file__).resolve().parents[2] / "presets" / "map.json"
preset = json.loads(source.read_text(encoding="utf-8"))["presets"]["master"]
# The translated Mac quick starts (guide/<locale>.html, bundled beside this page), one per preset language.
locales = json.loads((source.parent / "locales.json").read_text(encoding="utf-8"))
names = {"de": "Deutsch", "es": "Español", "fr": "Français", "it": "Italiano", "ja": "日本語", "ko": "한국어",
         "nl": "Nederlands", "pt-BR": "Português (Brasil)",
         "ru": "Русский", "tr": "Türkçe", "zh-CN": "简体中文", "zh-TW": "繁體中文"}
languages = " · ".join(f'<a href="guide/{code}.html" hreflang="{code}" lang="{code}">{html.escape(names.get(code, code))}</a>'
                       for code in sorted(locales))
rows = []
for row in preset["bindings"] + preset["nativeBindings"]:
    control = row["control"].replace("+", " + ").title()
    gesture = {"cw": "Clockwise", "ccw": "Counterclockwise", "press": "Press"}[row["gesture"]]
    if row.get("mode") == "release":
        gesture += " (on release)"
    rows.append("<tr>" + "".join("<td>" + html.escape(value) + "</td>" for value in [control, gesture, row["label"]]) + "</tr>")
labels = {row["action"]: row["label"] for row in preset["bindings"] + preset["menuBindings"]}
menu = "".join("<li>" + html.escape(labels[action]) + "</li>" for action in preset["tourMenu"]["actions"])
document = """<!doctype html>
<!-- SPDX-License-Identifier: GPL-2.0-or-later -->
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Fadester Companion — Mac quick guide</title>
<style>body{font:17px/1.6 system-ui,sans-serif;max-width:920px;margin:40px auto;padding:0 24px;color:#18302b;background:#fffefa}h1{line-height:1.15}h2{margin-top:2em}.note{background:#edf3ee;padding:16px;border-left:4px solid #456d5b}.twoway{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px;margin:20px 0}.card{background:#f3f6fb;border:1px solid #cdd7e6;border-radius:8px;padding:16px}table{width:100%;border-collapse:collapse;font-size:15px}th,td{text-align:left;padding:10px;border-bottom:1px solid #bacac0}th{background:#edf3ee}li{margin:.5em 0}code{overflow-wrap:anywhere}@media print{body{font-size:11pt;margin:0}tr{break-inside:avoid}h2{break-after:avoid}}</style>
<h1>Fadester Companion</h1><p>Mac edition · OBS Fadester for TourBox</p>
<p>Quick start in your language: __LANGUAGES__</p>
<p class="note">This Mac app is built and self-tested automatically for Apple silicon and Intel, but it is ad-hoc signed and not notarized, and its full control of OBS from a physical TourBox has not yet been rehearsed on a Mac. Native Mac import, Scroll press and Dial input were checked on one full-size TourBox through a remote USB connection. This does not establish every physical combination, every keyboard layout, or complete show readiness. Rehearse with your own idle test scenes before relying on it.</p>
<h2>First open</h2><p>Move <b>Fadester Companion.app</b> to Applications. The app is not notarized by Apple, so macOS refuses to open it the first time. Try to open it once, then go to <b>System Settings → Privacy &amp; Security</b>, scroll down and click <b>Open Anyway</b>. (On macOS 14 and older you can instead Control-click the app and choose <b>Open</b>, then <b>Open</b> again.)</p>
<div class="twoway">
<div class="card"><b>Opened Fadester Companion first?</b><br>Click <b>Import into TourBox Console</b>: it saves <code>OBS Fadester for TourBox.tb</code> in Downloads, copies its path and opens TourBox Console (the animated <b>Show me where to click</b> window plays the clicks). In Console click the middle <b>Import [↙]</b> icon beside Preset List, press ⌘⇧G, then ⌘V and Return in the file window, open the <code>.tb</code>, then turn <b>Auto Switch</b> off and select <b>OBS Fadester for TourBox</b>: one preset then works whichever app is in front. Only if you keep Auto Switch on, click <b>Not Linked</b> → pick <b>OBS</b> (not Fadester) → click <b>Save</b>, and link it to Google Chrome too to control videos with Chrome in front.</div>
<div class="card"><b>Opened TourBox Console first?</b><br>TourBox’s <code>.tb</code> files do not embed machine-specific app paths (even presets from <a href="https://www.tourboxtech.com/en/presets/">TourBox Preset Square</a> import as <b>Not Linked</b>). Turn <b>Auto Switch</b> off in Console and select <b>OBS Fadester for TourBox</b>, so it works whichever app is in front (with Auto Switch on, link it to <b>OBS</b>, and to Google Chrome for videos), and keep <b>Fadester Companion</b> open with <b>Controls: on</b>. (<a href="https://www.tourboxtech.com/en/downloads/">TourBox Console download</a>)</div>
</div>
<h2>Connect in five steps</h2><ol>
<li>Keep the complete application bundle together. Open <b>Fadester Companion</b>. Its top status lights and live interactive setup diagram check whether OBS and TourBox Console are open. The controls start by themselves once Accessibility is granted (step 4), unless you pressed <b>Stop</b> the last time.</li>
<li>Click <b>Import into TourBox Console</b>: it saves the embedded <code>OBS Fadester for TourBox.tb</code> (with its labels in the window’s language) to Downloads, copies its path and opens TourBox Console (Fadester Companion remembers the preset hash and tells you if a future app update includes a newer <code>.tb</code>; <b>Show me where to click</b> plays the clicks). macOS may ask once whether Fadester Companion may use the Downloads folder; if you say no, a save window asks where to put the file. In TourBox Console click the middle <b>Import [↙]</b> icon beside Preset List, press ⌘⇧G, then ⌘V and Return in the file window, open <code>OBS Fadester for TourBox.tb</code>, turn <b>Auto Switch</b> off and select <b>OBS Fadester for TourBox</b> (one preset then works with OBS, Chrome or any app in front). Only if you keep Auto Switch on, click <b>Not Linked</b> → pick <b>OBS</b> (not Fadester) → click <b>Save</b>, and link it to Google Chrome too. Mac shortcuts use <b>Control + Option + Shift</b> for the OBS actions and <b>Control + Shift</b> or <b>Option + Shift</b> for the video and layer actions; Command is absent. Do not import the Windows file.</li>
<li>Enable authenticated OBS WebSocket in <b>Tools → WebSocket Server Settings</b>. Fadester Companion reads the matching saved local password automatically (an override lasts only for the open app session). Discovery is strictly read-only. In Assignments select names, or leave unused roles unassigned: a D-pad anchor nobody chose uses the scene at that place in OBS’s scene list (anchor 1 = the first scene), and Layer 1 and Layer 2 fill themselves in from the live scene the first time a Top grip is used (Layer 1 = the topmost visible picture, Layer 2 = the next one down; sound-only and hidden sources are skipped) and are saved to Assignments. Save while the controls run applies assignments, inputs, anchors and steps at once; the port, VJster, game controller, mixer mode and fade step still need Stop and Start.</li>
<li>Click <b>Grant Accessibility to Fadester Companion…</b> and turn on <b>Fadester Companion</b> in <b>System Settings → Privacy &amp; Security → Accessibility</b>. If <b>Fadester Companion T-bar</b> (the helper that moves OBS’s T-bar) and <b>Fadester Companion Shortcuts</b> (the helper that receives the TourBox shortcuts) are listed too, turn them on as well. TourBox Console has separate permissions.</li>
<li>Use OBS 33, Studio Mode (when it is off, the <b>OBS</b> light at the top of the window has a <b>Turn on</b> button), a Fade among OBS's scene transitions, two different scenes and a visible T-bar at its starting end. Wait for <b>Controls: on</b> at the top of the window (if the light says <b>off</b>, click <b>Start</b> beside it), then check that Console has <b>OBS Fadester for TourBox</b> selected. If the T-bar cannot be read yet, the other controls still work and the status line says why.</li></ol>
<h2>First rehearsal</h2><p>Press Scroll for the Program and Preview names in Activity. Turn Scroll to put another scene in Preview. The flat Dial drives the native manual mix; Side + Dial rides Music. The raised Knob steps VJster video speed (press + turn for fine 0.05x, tap Side or press Side + Knob to return to 1x) in Chrome YouTube or an OBS Browser Source pointed at the copied <code>/obs</code> URL; press + turn Scroll steps quality, a Knob press toggles play/pause and Side + D-pad Up reads the video. Top + Dial rides Layer 2 opacity, Top + Knob steps Layer 1 blend modes, and Top + Scroll steps Layer 2 blend modes. Stop partway to hold the blend. Side + Dial press cancels. Clockwise always moves the T-bar towards Preview: after a throw, pause a moment and turn clockwise again for the next one. T-bar left/right describe counterclockwise/clockwise control directions; they do not permanently identify either scene.</p>
<p>Tall sends Preview to Program and Top cuts from rest; during a partial manual mix either finishes that mix. A tap on Side returns the video to 1x. A tap on Short reads recording status (read-only); Undo last audio change is in the Tour menu. Side, Top, Tall and Short act on release. Rehearse each held combination and confirm there is no unwanted single-button action when released.</p>
<p>Tour opens the menu at the pointer. Scroll selects, Tall confirms, Short dismisses. Verify these menu gestures on your Console before using them live. General HUD in Console offers a compact assignment card.</p>
<h2>Optional whole mix</h2><p>Leave it off for initial rehearsal. When enabled, Side + Knob and compatible local clients can control all eligible public OBS audio inputs together. This affects their tracks and monitors. It preserves mute states; it is not a stream-only master. Newly added inputs may be heard before discovery. Stop does not restore levels. Use the same configuration and the explicit Restore whole mix action to recover an owned fade.</p>
<h2 id="recovery">Stop and recover</h2><p>Closing the window with the controls on only hides it: the app stays in the menu bar at the top right of the screen, and <b>Quit Fadester Companion</b> in that icon's menu stops the controls. <b>Stop</b> releases the owned shortcuts and closes the host. It does not finish or cancel a partial transition or raise audio. Check OBS after interruption; never assume a stopped app restored the show. Activity reports refusals. If a source is renamed, read the current catalog, reassign it and click Save. A missing saved target is retained as Unavailable, never silently replaced.</p>
<p>The app saves its assignments to <code>~/Library/Application Support/FadesterTourBox/panel-config.json</code>, without a password. It does not overwrite a malformed settings file. To uninstall, stop and quit the app, remove the preset in Console if desired, and delete the app. Keep settings and mix-state files until you have reviewed any pending audio recovery.</p>
<h2>Complete physical map</h2><table><thead><tr><th>Control</th><th>Gesture</th><th>Action</th></tr></thead><tbody>__ROWS__</tbody></table>
<h2>Tour menu</h2><ol>__MENU__</ol><p>The preset’s labels and the quick start come in 13 languages; the shortcuts are the same in all of them. Keyboard layouts other than US/ABC have not been tested yet. The app is ad-hoc signed, not notarized.</p>
<p>Fadester Companion__VERSION__ · Offline quick guide</p></html>"""
# python make-guide.py OUTPUT.html [VERSION]: build.sh passes the version, and the guide's last line shows it.
version = " " + sys.argv[2] if len(sys.argv) > 2 and sys.argv[2].replace(".", "").replace("-", "").isalnum() else ""
Path(sys.argv[1]).write_text(document.replace("__ROWS__", "".join(rows)).replace("__MENU__", menu).replace("__LANGUAGES__", languages).replace("__VERSION__", version), encoding="utf-8")
